  demoOnly: true,
  sessions: [
    { sessionId: 'FAKE-SESSION-4001', fakeClientId: 'FAKE-CLIENT-3001', date: '2026-04-20', clinicianId: 'DEMO-CLIN-01', fee: 145 },
    { sessionId: 'FAKE-SESSION-4002', fakeClientId: 'FAKE-CLIENT-3002', date: '2026-04-21', clinicianId: 'DEMO-CLIN-02', fee: 165 },
    { sessionId: 'FAKE-SESSION-4003', fakeClientId: 'FAKE-CLIENT-3003', date: '2026-04-22', clinicianId: 'DEMO-CLIN-01', fee: 145 }
  ],
  claims: [
    { claimId: 'FAKE-CLAIM-5001', sessionId: 'FAKE-SESSION-4001', status: 'paid', paidAmount: 112 },
    { claimId: 'FAKE-CLAIM-5002', sessionId: 'FAKE-SESSION-4002', status: 'denied', paidAmount: 0, denialReason: 'demo missing prior authorization' }
  ]
};
return [{ json: data }];

if ($json.demoOnly !== true) {
  throw new Error('Demo guard blocked execution. This simulated workflow accepts fake data only.');
}
return [{ json: { ...$json, guard: 'passed-fake-data-only' } }];

const claimsBySession = new Map($json.claims.map((claim) => [claim.sessionId, claim]));
const findings = $json.sessions.map((session) => {
  const claim = claimsBySession.get(session.sessionId);
  if (!claim) {
    return { type: 'missing-claim', sessionId: session.sessionId, modeledRecoveryValue: session.fee, action: 'Create claim review task' };
  }
  if (claim.status === 'denied') {
    return { type: 'denied-claim', sessionId: session.sessionId, claimId: claim.claimId, modeledRecoveryValue: session.fee, denialReason: claim.denialReason, action: 'Create denial review task' };
  }
  return { type: 'matched-paid', sessionId: session.sessionId, claimId: claim.claimId, modeledRecoveryValue: 0, action: 'No action' };
});
return findings.map((finding) => ({ json: { ...finding, demoOnly: true, productionWarning: 'Requires BAA-covered EHR/billing access and approved retention settings before real use.' } }));
